  },
  [7629] = {
    title = "瓶中的小鬼",
    objectives = "把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。",
  },
  [7630] = {
    title = "奥金锭",
    objectives = "把1块奥金锭交给燃烧平原的戈瑟奇·邪眼。",
  },
  [7631] = {
    title = "克索诺斯恐惧战马",
    objectives = "阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。",
  },
  [7632] = {
    title = "远古石叶",
    objectives = "找到远古石叶的主人。祝你好运，$N。这个世界是很大的。",
  },
  [7633] = {
    title = "介绍",
    objectives = "",
  },
  [7634] = {
    title = "龙筋箭袋",
    objectives = "费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。",
  },
  [7635] = {
    title = "合适的弓弦",
    objectives = "费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。",
  },
  [7636] = {
    title = "古树的手杖",
    objectives = "你必须找到并干掉下列4个恶魔：$B$B迷人的西蒙妮。$B$B疯狂的克林弗兰。$B$BS屠杀者索伦诺尔。$B$B摧毁者阿托留斯。$B$B杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。$B$B根据你背包中的石化树皮来找到它们所在位置的线索。$B$B你必须独自完成这个任务。",
  },
  [7637] = {
    title = "牺牲精神",
    objectives = "到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。",
  },
  [7638] = {
    title = "格雷森·沙东布瑞克公爵",
    objectives = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。",
  },
  [7639] = {
    title = "圣骑士的审判",
    objectives = "把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
  },
  [7640] = {
    title = "恐惧谷的灵魂",
    objectives = "使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。",
  },
  [7641] = {
    title = "格瑞曼德·艾尔默",
    objectives = "与暴风城矮人区的格瑞曼德·艾尔默谈一谈。",
  },
  [7642] = {
    title = "收集材料",
    objectives = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。",
  },
  [7643] = {
    title = "上古圣马之魂",
    objectives = "你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。$B$B到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。",
  },
  [7644] = {
    title = "被祝福的奥金马铠",
    objectives = "将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
  },
  [7645] = {
    title = "魔法粮草",
    objectives = "把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。$B$B你还需要给她50金币来对她进行安抚。",
  },
  [7646] = {
    title = "预言水晶球",
    objectives = "把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
  },
  [7647] = {
    title = "审判和救赎",
    objectives = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。$B$B把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。",
  },
  [7648] = {
