  [7701] = {
    title = "悬赏：工头玛托留斯",
    objectives = "那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。$B$B杀死工头玛托留斯，将他的徽记交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。",
  },
  [7702] = {
    title = "让他们失眠！",
    objectives = "在大熔炉的熔渣之池深处，你可以发现黑铁矮人的休息区。$B$B到休息区去偷走20只黑铁枕头。当你完成任务后就回到灼热峡谷的艾沃奈斯那里复命。",
  },
  [7703] = {
    title = "戈多克食人魔的事务",
    objectives = "找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。",
  },
  [7704] = {
