  [7839] = {
    title = "邪枝窃贼",
    objectives = "辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。$B$B你记得铁匠斯拉提说过，你可以在辛特兰东北部的某个邪枝巨魔神庙中找到它，要不然就是在隐匿石那边。",
  },
  [7840] = {
    title = "拉尔德的午餐",
    objectives = "辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。$B$B拉尔德说他把午餐留在了北面的岛上。当心邪枝巨魔。",
  },
  [7841] = {
    title = "给蛮锤部族的警告",
    objectives = "辛特兰恶齿村的奥索·莫吉克要你去杀掉8个高原前锋、5个高原斥候和2个高原神射手。任务完成之后回到他那里去复命。$B$B你可以在辛特兰西北部的奎尔丹尼小屋找到那些高原精灵。",
  },
  [7842] = {
    title = "又一个给蛮锤部族的警告",
    objectives = "辛特兰恶齿村的奥索·莫吉克要你从辛特兰的狮鹫身上收集1根细长的狮鹫羽毛。任务完成之后回到他那里去复命。$B$B在辛特兰各处都有狮鹫出没。",
  },
  [7843] = {
    title = "给蛮锤部族的最后警告",
    objectives = "辛特兰恶齿村的奥索·莫吉克要你去辛特兰西部的鹰巢山，把给蛮锤部族的警告插在城镇中心的水井旁边。任务完成之后回到他那里去复命。$B$B当心那些愤怒的蛮锤矮人以及野蛮的联盟成员。",
  },
  [7844] = {
    title = "野蛮的亲戚",
    objectives = "辛特兰恶齿村的秘法师雅尔金要你去杀掉6个邪枝割颅者和2个邪枝占卜者。任务完成之后回到他那里去复命。$B$B秘法师雅尔金说过，你可以在辛特兰东北部的沙尔瓦萨和亚戈瓦萨神庙附近找到那些巨魔。",
  },
  [7845] = {
    title = "被绑架的断齿长者！",
    objectives = "辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。$B$B你听说他被关在辛萨罗顶部，辛萨罗位于辛特兰的南部地区，那里是邪枝巨魔的主城。",
  },
  [7846] = {
    title = "找回钥匙！",
    objectives = "辛萨罗的断齿长者要求你杀掉守护者希坦亚，并用她身上的镣铐钥匙打开他的镣铐。当你找到钥匙之后就回到他那里去。",
  },
  [7847] = {
    title = "向断齿族长复命",
    objectives = "辛萨罗的断齿长者要求你将他已经被营救的消息带给恶齿村的断齿族长。",
  },
  [7848] = {
    title = "熔火之心的传送门",
    objectives = "进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。",
  },
  [7849] = {
    title = "分离的痛苦",
    objectives = "辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的徽记和猎户莫克霍尔的骨头交给猎户马克霍尔。$B$B马克霍尔说过，他兄弟的尸体被软泥怪和邪枝巨魔的狼群分食。他还提到在辛萨罗有个大坑，里面全都是软泥怪，那里还有个狼穴。这两个地方都在靠近辛萨罗神庙顶部的区域。",
  },
  [7850] = {
    title = "黑暗之瓶",
    objectives = "辛特兰恶齿村的断齿族长要你在辛萨罗找到5瓶腐化之血。任务完成之后就回到断齿族长那里。",
  },
  [7861] = {
    title = "通缉：邪恶祭司海克斯和她的爪牙",
    objectives = "你必须杀掉邪恶祭司海克斯和5名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。$B$B你可以在辛特兰的邪枝巨魔城市辛萨罗的顶部找到他们。",
  },
  [7862] = {
    title = "职位空缺：恶齿村卫兵队长",
    objectives = "你必须消灭5个邪枝狂战士、3个邪枝暗影猎手、3个邪枝饮血者和3个邪枝噬魂者。$B$B完成任务之后向辛特兰恶齿村的断齿族长复命。",
  },
