  [8301] = {
    title = "正义之路",
    objectives = "希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯想要你杀死亚什虫巢、佐拉虫巢和雷戈虫巢中的异种虫类。从死去的虫子尸体上收集异种蝎壳碎片。当你收集到200块异种蝎壳碎片时，回到巴里斯托尔斯那儿去。$B$B作为一名诺兹多姆的特使，只有你和你的副官可以从异种虫类的尸体上拾取异种蝎壳碎片。请注意保持你的包裹空间足够多。",
  },
  [8302] = {
